import fs from 'node:fs';
import { chromium } from 'playwright-core';
const candidates=[process.env.CHROME_PATH,'/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].filter(Boolean);
const executablePath=candidates.find(p=>fs.existsSync(p));
if(!executablePath)throw new Error('No Chrome/Chromium executable found on runner');
const browser=await chromium.launch({headless:true,executablePath,args:['--no-sandbox','--autoplay-policy=no-user-gesture-required']});
const context=await browser.newContext({viewport:{width:1440,height:1000},locale:'ko-KR'});
const page=await context.newPage();
const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:4173/player/',{waitUntil:'networkidle'});
const visible=async sel=>{if(!(await page.locator(sel).isVisible()))throw new Error(`${sel} not visible`)};
await visible('[data-scene-mode="journey"]');await visible('#durationDirect');
await page.locator('[data-scene-mode="simple"]').click();await visible('[data-scene-content="simple"]');await visible('.plugin-rack');
if(await page.locator('#builtInPresets .preset-card').count()<1)throw new Error('Simple Scenes did not render');
await page.locator('[data-view="mixer"]').first().click();await visible('[data-panel="mixer"]');if(await page.locator('#mixerGrid .mixer-source').count()!==21)throw new Error('Mixer catalog is not 21 sources');
await page.locator('[data-view="timer"]').first().click();await visible('[data-panel="timer"]');await page.locator('[data-timer-minutes="15"]').click();if((await page.locator('#timerRemaining').textContent())?.trim()==='꺼짐')throw new Error('Sleep timer did not start');
await page.locator('[data-view="settings"]').first().click();await visible('[data-panel="settings"]');await page.locator('#themeSelect').selectOption('light');if(await page.locator('html').getAttribute('data-theme')!=='light')throw new Error('Theme setting failed');
const master=page.locator('[data-panel="settings"] .master-volume');await master.evaluate(el=>{el.value='42';el.dispatchEvent(new Event('input',{bubbles:true}))});
await page.locator('[data-view="scene"]').first().click();await page.locator('[data-scene-mode="journey"]').click();await visible('[data-scene-content="journey"]');
await page.locator('[data-duration="600"]').click();if(!(await page.locator('#durationOutput').textContent())?.includes('10h'))throw new Error('10h shortcut failed');
await page.locator('#durationDirect').fill('10:15');await page.locator('#durationDirectApply').click();await page.waitForTimeout(40);const direct=await page.evaluate(()=>({output:document.querySelector('#durationOutput')?.textContent,input:document.querySelector('#durationDirect')?.value,slider:document.querySelector('#durationSlider')?.value}));if(!direct.output?.includes('10h 15m')||direct.input!=='10:15'||direct.slider!=='615')throw new Error(`HH:MM failed: ${JSON.stringify(direct)}`);
await page.locator('.language-toggle').click();if((await page.locator('[data-scene-mode="simple"]').textContent())?.trim()!=='Simple Scenes')throw new Error('Language toggle failed');
await page.locator('[data-scene-mode="simple"]').click();await visible('.plugin-rack');await page.locator('#warmthPlugin').evaluate(el=>{el.value='4';el.dispatchEvent(new Event('input',{bubbles:true}))});if((await page.locator('#warmthOut').textContent())?.trim()!=='4 dB')throw new Error('Warmth DSP failed');
if(errors.length)throw new Error(`browser errors: ${errors.join(' | ')}`);
await browser.close();console.log('web interaction smoke test passed');
